import requests

def test_whatsapp_webhook_receiver():
    base_url = "http://localhost:4000/api"
    url = f"{base_url}/whatsapp/webhook"
    timeout = 30

    # Example valid webhook payload, typical structure for WhatsApp webhook events
    payload = {
        "object": "whatsapp_business_account",
        "entry": [
            {
                "id": "WHATSAPP_BUSINESS_ACCOUNT_ID",
                "changes": [
                    {
                        "value": {
                            "messages": [
                                {
                                    "from": "1234567890",
                                    "id": "wamid.ID",
                                    "timestamp": "1626105600",
                                    "text": {
                                        "body": "Hello World"
                                    },
                                    "type": "text"
                                }
                            ],
                            "metadata": {
                                "display_phone_number": "PHONE_NUMBER",
                                "phone_number_id": "WHATSAPP_PHONE_NUMBER_ID"
                            }
                        },
                        "field": "messages"
                    }
                ]
            }
        ]
    }

    headers = {
        "Content-Type": "application/json"
    }

    try:
        response = requests.post(url, json=payload, headers=headers, timeout=timeout)
    except requests.RequestException as e:
        assert False, f"Request failed: {e}"

    assert response.status_code == 201, f"Expected status code 201, got {response.status_code}"

    try:
        resp_json = response.json()
    except ValueError:
        assert False, "Response is not JSON"

    # Validate response body structure and content
    assert "data" in resp_json, "Response JSON missing 'data' key"
    assert isinstance(resp_json["data"], dict), "'data' should be a dictionary"
    assert resp_json["data"].get("status") == "ok", "Expected data.status to be 'ok'"
    assert "meta" in resp_json, "Response JSON missing 'meta' key"

test_whatsapp_webhook_receiver()

import requests
import uuid

BASE_URL = "http://localhost:4000/api"
TIMEOUT = 30


def test_automation_rule_creation_with_valid_data():
    # Step 1: Register unique user
    register_url = f"{BASE_URL}/auth/register"
    unique_email = f"testuser_{uuid.uuid4()}@example.com"
    register_payload = {
        "email": unique_email,
        "password": "TestPassword123!"
    }
    headers = {
        "Content-Type": "application/json"
    }
    try:
        register_response = requests.post(register_url, json=register_payload, headers=headers, timeout=TIMEOUT)
        assert register_response.status_code == 201, f"Expected 201 on register, got {register_response.status_code}"
    except requests.RequestException as e:
        assert False, f"Register request failed: {e}"

    # Step 2: Login to get access_token
    login_url = f"{BASE_URL}/auth/login"
    login_payload = {
        "email": unique_email,
        "password": "TestPassword123!"
    }
    try:
        login_response = requests.post(login_url, json=login_payload, headers=headers, timeout=TIMEOUT)
        assert login_response.status_code == 200, f"Expected 200 on login, got {login_response.status_code}"
        login_data = login_response.json()
        access_token = login_data.get("access_token")
        assert access_token, "No access_token found in login response"
    except requests.RequestException as e:
        assert False, f"Login request failed: {e}"

    # Step 3: Create chatbot automation flow as per PRD
    chatbot_flow_url = f"{BASE_URL}/chatbot/flows"
    chatbot_flow_payload = {
        "name": "Test Flow",
        "steps": [
            {
                "type": "send_message",
                "message": {
                    "text": "Hello!"
                }
            }
        ]
    }
    auth_headers = {
        "Content-Type": "application/json",
        "Authorization": f"Bearer {access_token}"
    }
    try:
        flow_response = requests.post(chatbot_flow_url, json=chatbot_flow_payload, headers=auth_headers, timeout=TIMEOUT)
        assert flow_response.status_code == 201, f"Expected 201 on chatbot flow creation, got {flow_response.status_code}"
        flow_data = flow_response.json()
        flow_id = flow_data.get("id") or flow_data.get("data", {}).get("id")
        assert flow_id, "No 'id' found in chatbot flow creation response"
    except requests.RequestException as e:
        assert False, f"Chatbot flow creation request failed: {e}"


test_automation_rule_creation_with_valid_data()
